import crypto from 'crypto';
import { EventEmitter } from 'events';

interface TokenConfig {
  tokenLength: number;
  maxRetries: number;
  rateLimitWindow: number;
  maxRequestsPerWindow: number;
}

interface RateLimitEntry {
  count: number;
  windowStart: number;
}

class EntropyPool {
  private pool: Buffer;
  private position: number;
  private readonly poolSize: number;

  constructor(poolSize: number = 256) {
    this.poolSize = poolSize;
    this.pool = crypto.randomBytes(poolSize);
    this.position = 0;
  }

  getBytes(count: number): Buffer {
    if (this.position + count > this.poolSize) {
      this.refill();
    }
    const result = this.pool.slice(this.position, this.position + count);
    this.position += count;
    return result;
  }

  private refill(): void {
    this.pool = crypto.randomBytes(this.poolSize);
    this.position = 0;
  }
}

class TokenService extends EventEmitter {
  private config: TokenConfig;
  private rateLimitMap: Map<string, RateLimitEntry>;
  private entropyPool: EntropyPool;
  private retryState: Map<string, number>;

  constructor(config: TokenConfig) {
    super();
    this.config = config;
    this.rateLimitMap = new Map();
    this.entropyPool = new EntropyPool();
    this.retryState = new Map();
  }

  private checkRateLimit(clientId: string): boolean {
    const now = Date.now();
    const entry = this.rateLimitMap.get(clientId);

    if (!entry || (now - entry.windowStart) > this.config.rateLimitWindow) {
      this.rateLimitMap.set(clientId, { count: 1, windowStart: now });
      return true;
    }

    if (entry.count >= this.config.maxRequestsPerWindow) {
      return false;
    }

    entry.count++;
    return true;
  }

  private generateTokenBytes(length: number): Buffer {
    return this.entropyPool.getBytes(length);
  }

  private async attemptGeneration(clientId: string, attempt: number): Promise<string> {
    if (!this.checkRateLimit(clientId)) {
      throw new Error('RATE_LIMITED');
    }

    const tokenBytes = this.generateTokenBytes(this.config.tokenLength);
    const token = tokenBytes.toString('hex');

    // Validate token meets minimum entropy requirements
    const uniqueBytes = new Set(tokenBytes);
    if (uniqueBytes.size < Math.min(4, this.config.tokenLength)) {
      throw new Error('INSUFFICIENT_ENTROPY');
    }

    this.emit('token_generated', { clientId, attempt, tokenLength: token.length });
    return token;
  }

  async generateToken(clientId: string): Promise<string> {
    let lastError: Error | null = null;

    for (let attempt = 0; attempt < this.config.maxRetries; attempt++) {
      try {
        const token = await this.attemptGeneration(clientId, attempt);
        this.retryState.delete(clientId);
        return token;
      } catch (error) {
        lastError = error as Error;
        if ((error as Error).message === 'RATE_LIMITED') {
          const backoff = Math.pow(2, attempt) * 100;
          await new Promise(resolve => setTimeout(resolve, backoff));
        }
        this.retryState.set(clientId, attempt + 1);
      }
    }

    throw lastError || new Error('TOKEN_GENERATION_FAILED');
  }
}

// Service initialization
const tokenService = new TokenService({
  tokenLength: 32,
  maxRetries: 3,
  rateLimitWindow: 60000,
  maxRequestsPerWindow: 100
});

export { TokenService, tokenService, TokenConfig };
